attempts.query:
PREFIX oncologia: <https://w3id.org/rastro/oncologia#>
SELECT (COUNT(DISTINCT ?t) AS ?n) WHERE {
  ?t a oncologia:Trial ; oncologia:status ?s ; oncologia:testsDrug ?d .
  FILTER(?s IN ("RECRUITING", "ACTIVE_NOT_RECRUITING", "NOT_YET_RECRUITING", "ENROLLING_BY_INVITATION"))
  ?d oncologia:name "PEMBROLIZUMAB" .
}
